<template><div class="result"><a-card :bordered="false" class="card"><div class="mark">✓</div><div class="eyebrow">ACTIVITY / PARTICIPATION</div><h1>参与成功</h1><p>你已加入「{{title||'本次活动'}}」，奖励积分将进入会员积分流水。</p><div class="reward">+100 <span>积分</span></div><div class="actions"><a-button type="primary" size="large" @click="$router.push('/membership/points')">查看积分</a-button><a-button size="large" @click="$router.push('/activity/my')">我的活动</a-button><a-button size="large" @click="$router.push('/activity')">继续逛活动</a-button></div></a-card></div></template>
<script setup>
import {ref,onMounted} from 'vue';import {activityApi} from '../api'
const title=ref('');onMounted(async()=>{try{const id=location.pathname.split('/')[2];const list=(await activityApi.list())||[];title.value=list.find(x=>String(x.activityId)===String(id))?.title||''}catch(e){}})
</script>
